import Foundation

/// Decides whether a copy should never be kept in the history.
public enum SensitiveSource {
    /// Pasteboard types that password managers and other apps add to mark a copy as secret or temporary.
    public static let flaggedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "net.antelle.keeweb",
        "com.typeit4me.clipping",
    ]

    /// Fragments of the bundle IDs of password managers. Some never flag their copies, so the app
    /// that was in front when the clipboard changed is checked too.
    private static let managerFragments = [
        "onepassword", "1password", "bitwarden", "lastpass", "dashlane", "keepass", "enpass",
        "nordpass", "proton.pass", "protonpass", "keepersecurity", "callpod.keeper", "roboform", "keychainaccess",
    ]
    private static let managerExactIDs: Set<String> = ["com.apple.passwords", "com.apple.keychainaccess"]

    public static func isPasswordManager(bundleID: String?) -> Bool {
        guard let id = bundleID?.lowercased(), !id.isEmpty else { return false }
        return managerExactIDs.contains(id) || managerFragments.contains { id.contains($0) }
    }

    public static func isFlagged(types: Set<String>) -> Bool {
        !types.isDisjoint(with: flaggedTypes)
    }
}
